# -*- coding: utf-8 -*-"""bootstrap_rebuild.py — 新设备「一键重建画廊」：从本地 AssetBundles 出发，跑到能打开画廊。为什么要有它：README 的「快速上手」只给了三条命令，真正的全量重建散在 WF-7 / WF-12 / WF-15 /WF-17 / WF-21 五个工作流里（立绘、Spine、Live2D 三步、语音、索引/缩略图/部署），换机器时要靠人肉拼接、还要记住每步的判据与先后顺序。这里把它压成一条命令 + 一份步骤表。**它不是新管线**：每个步骤都只是调用既有脚本（与 `update_pipeline.py` 的增量阶段同源），本文件只负责「顺序 / 可续跑 / 判据 / 日志」。用法:  py -3 scripts/bootstrap_rebuild.py --plan          # 只看要做什么（不写盘、不装依赖）  py -3 scripts/bootstrap_rebuild.py --yes           # 真跑（会写 Output/，小时级）  py -3 scripts/bootstrap_rebuild.py --yes --only live2d,index  py -3 scripts/bootstrap_rebuild.py --yes --from audio --skip cg  py -3 scripts/bootstrap_rebuild.py --yes --install-deps   # 缺依赖时自动 pip install判据（每步都机械判，不看退出码 —— 这些脚本历史上"失败仍 exit 0"过）：  步骤的 marker 必须出现在该步 stdout（或它的进度日志文件里），否则判红停下。⚠️ 全量小时级 ⇒ 建议脱离宿主进程跑（见 docs/WORKFLOWS.md WF-32「长时批处理」）：  Windows:  start "" /b py -3 scripts/bootstrap_rebuild.py --yes > .diag\\bootstrap.out 2>&1"""import argparseimport osimport subprocessimport sysimport timesys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))import paths as P  # noqa: E402sys.stdout.reconfigure(encoding='utf-8', errors='replace')PY = sys.executableLOG = os.path.join(P.OUT, 'bootstrap_rebuild.log')ENV = {**os.environ, 'PYTHONIOENCODING': 'utf-8'}def _c(*a):    return [PY] + list(a)# key, 标题, [(命令, marker 或 marker 文件), …], 依赖的工具（缺了跳过并提示）STEPS = [    ('scan', '扫描源包 → asset_manifest.json',     [(_c('scripts/scan_assets.py'), '清单已写入')], []),    ('deps', '重建官方依赖表 → Output/dependency_manifest.json',     [(_c('scripts/export_dependency_manifest.py',          '--out', P.MANIFEST_PATH), '条目')], []),    ('spine', 'Spine 动态立绘全量提取 → Output/Spine_v2',     [(_c('scripts/run_v2_full.py', '--only', 'spine'), 'Spine 阶段完成')], []),    ('paintings', '静态立绘全量合成 → Output/Paintings_v2',     [(_c('scripts/run_v2_full.py', '--only', 'static'), 'STATIC-DONE')], []),    ('live2d', 'Live2D 还原 + 动作 + model3 修复 → Output/Live2D',     [(_c('scripts/reconstruct_live2d.py', '--all'), '完成! 成功'),      (_c('scripts/extract_motions.py', '--all', '--into-production'), '[SUMMARY] 模型'),      (_c('scripts/fix_model3.py'), 'Fixed')], []),    ('audio', '语音（CV2 皮肤级）+ ACB 解码 → Output/Audio',     [(_c('scripts/extract_cv_voice.py', '--all'), 'file:Output/gallery_v2/skin_voice.json'),      (_c('scripts/export_cue_audio.py'), 'Done! Time')], ['vgmstream']),    ('cg', 'Spine 全屏 CG 批量导出 → Output/CG_v2（要 Chrome）',     [(_c('scripts/diag/run_cg_export.py', '--size', '2400', '--extra', 'animFrame=1', '--redo'),       '完成')], ['chrome']),    ('index', '索引 / 缩略图 / 部署 → Output/gallery_v2',     [(_c('scripts/build_gallery_index.py'), 'DONE'),      (_c('scripts/make_thumbs.py'), '完成 ok='),      (_c('scripts/deploy_gallery.py'), '完成，同步')], []),    ('vendor', '画廊运行库补齐（按 vendor/MANIFEST.json 的 sha256）',     [(_c('scripts/fetch_gallery_vendor.py'), '')], []),]KEYS = [s[0] for s in STEPS]def log(msg, tee=True):    line = f'[{time.strftime("%H:%M:%S")}] {msg}'    print(line, flush=True)    if tee:        try:            os.makedirs(P.OUT, exist_ok=True)            with open(LOG, 'a', encoding='utf-8') as f:                f.write(line + '\n')        except OSError:            passdef tool_missing(names):    """步骤依赖的外部工具缺哪些（返回缺失清单）。"""    have = {'vgmstream': P.VGMSTREAM, 'ffmpeg': P.FFMPEG, 'chrome': P.CHROME,            'adb': P.MUMU_ADB, 'assetstudio': P.ASSETSTUDIO}    return [n for n in names if not have.get(n)]def run_step(key, title, cmds, needs, only_missing_ok=False):    miss = tool_missing(needs)    if miss:        log(f'[skip] {key} — 缺工具 {miss}（装好再单独跑：--only {key}）')        return None    log(f'== {key}: {title}')    for argv, marker in cmds:        shown = ' '.join(os.path.basename(argv[0]) if i == 0 else a for i, a in enumerate(argv))        log(f'   $ {shown}')        t0 = time.time()        try:            p = subprocess.run(argv, cwd=P.ROOT, env=ENV, capture_output=True,                               text=True, encoding='utf-8', errors='replace')        except FileNotFoundError as e:            log(f'   XX 启动失败：{e}')            return False        out = (p.stdout or '') + (p.stderr or '')        tail = '\n'.join(out.strip().splitlines()[-12:])        log(f'   退出码 {p.returncode}  用时 {time.time() - t0:.0f}s')        if tail:            print('   ' + tail.replace('\n', '\n   '), flush=True)        # 判据：这些脚本历史上"失败仍 exit 0"（见 WF-15/WF-23），所以认 marker 不认退出码。        # marker 两种写法：普通字面量（出现在输出里） / `file:<相对路径>`（文件存在且是本次新写的）        if marker.startswith('file:'):            fp = os.path.join(P.ROOT, marker[5:])            fresh = os.path.isfile(fp) and os.path.getmtime(fp) >= t0 - 1            if not fresh:                log(f'   XX 判据失败：{marker[5:]} 不存在或不是本次产出 ⇒ 停下')                return False            log(f'   OK 判据：{marker[5:]} 本次已更新')            continue        if marker and marker not in out:            log(f'   XX 判据失败：输出里没有 {marker!r} ⇒ 判为未完成/被截断，停下')            return False        if not marker and p.returncode != 0:            log('   XX 退出码非 0（该步无 marker 判据）')            return False    return Truedef preflight(install_deps):    """必需项体检（复用 check_toolchain.py，同一套判据，别在两边各写一份）。"""    r = subprocess.run([PY, 'scripts/diag/check_toolchain.py', '--json'], cwd=P.ROOT,                       env=ENV, capture_output=True, text=True, encoding='utf-8', errors='replace')    try:        import json        info = json.loads(r.stdout)    except Exception:        log('XX 体检脚本没给出 JSON ⇒ 先修 check_toolchain.py')        return False    miss = info.get('required_missing') or []    if not miss:        return True    log(f'XX 必需项缺 {len(miss)} 个：{"；".join(miss)}')    if install_deps and any('Python 依赖' in m for m in miss):        log('   --install-deps：尝试 py -3 -m pip install UnityPy Pillow')        subprocess.run([PY, '-m', 'pip', 'install', 'UnityPy', 'Pillow'], cwd=P.ROOT, env=ENV)        return preflight(False)    if any('files/AssetBundles' in m for m in miss):        log(f'   源包不在 {P.AB}。两种补齐方式：')        log('     ① 从模拟器增量拉：py -3 scripts/mumu_sync.py sync --apply')        log('     ② 已有备份就拷到该路径（或设 AL_ASSETS_ROOT 指向含 files/ 的根）')    return Falsedef main():    ap = argparse.ArgumentParser(description='新设备一键重建画廊（从本地 AssetBundles 出发）')    ap.add_argument('--plan', action='store_true', help='只打印步骤表与判据，不写盘')    ap.add_argument('--yes', action='store_true', help='真跑（会写 Output/，小时级）')    ap.add_argument('--only', default='', help='只跑这些步骤（逗号分隔）：' + ','.join(KEYS))    ap.add_argument('--skip', default='', help='跳过这些步骤（逗号分隔）')    ap.add_argument('--from', dest='start', default='', help='从某步开始（含）')    ap.add_argument('--install-deps', action='store_true', help='缺 UnityPy/Pillow 时自动 pip 安装')    a = ap.parse_args()    only = [x for x in a.only.split(',') if x]    skip = [x for x in a.skip.split(',') if x]    todo = [s for s in STEPS if (not only or s[0] in only) and s[0] not in skip]    if a.start:        if a.start not in KEYS:            print(f'[ERROR] --from 只认 {KEYS}')            return 2        todo = todo[[s[0] for s in todo].index(a.start):] if a.start in [s[0] for s in todo] else []    print(f'仓库根 {P.ROOT}\n产物根 {P.OUT}\n')    print(f'{"步骤":<12} 做什么 / 判据')    print('-' * 96)    for key, title, cmds, needs in STEPS:        flag = '→ 本次要跑' if any(s[0] == key for s in todo) else ('  跳过' if key in skip else '')        print(f'{key:<12} {title}   {flag}')        for argv, marker in cmds:            print(f'{"":12}   · {" ".join(argv[1:])}   [{marker}]')        if needs:            print(f'{"":12}   依赖工具: {", ".join(needs)}'                  f'{"  ⚠️ 当前缺 " + str(tool_missing(needs)) if tool_missing(needs) else ""}')    if not a.yes:        print('\n[dry-run] 未给 --yes ⇒ 什么都没跑。')        print('  真跑：py -3 scripts/bootstrap_rebuild.py --yes')        print('  长时建议脱离宿主进程（WF-32）：start "" /b py -3 scripts/bootstrap_rebuild.py --yes '              '> .diag\\bootstrap.out 2>&1')        return 0    if not preflight(a.install_deps):        return 2    log(f'=== 一键重建开始（{len(todo)} 个步骤）==> {LOG}')    done, skipped, failed = [], [], None    for key, title, cmds, needs in todo:        r = run_step(key, title, cmds, needs)        if r is None:            skipped.append(key)        elif r:            done.append(key)        else:            failed = key            break    log(f'=== 结束：完成 {len(done)} {done}｜跳过 {len(skipped)} {skipped}｜'        f'{"失败于 " + failed if failed else "无失败"}')    if failed:        log('  修好该步后从断点续跑：--from ' + failed)    return 1 if failed else 0if __name__ == '__main__':    sys.exit(main())